from pathlib import Path

ROOT = Path('/app') if Path('/app/scenario.json').exists() else Path(__file__).resolve().parents[1]
CONFIG_PATH = Path('/app/scenario.json') if Path('/app/scenario.json').exists() else ROOT / 'data/input.json'
CONFIG = json.loads(CONFIG_PATH.read_text())
INPUT = json.loads((ROOT / 'data/workload.json').read_text())
PARSER = argparse.ArgumentParser()
PARSER.add_argument('--stage', required=True, choices=CONFIG['stages'])
PARSER.add_argument('--output', default=str(ROOT / 'outputs'))
ARGS = PARSER.parse_args()
OUT = Path(ARGS.output)
OUT.mkdir(parents=True, exist_ok=True)
STAGE = ARGS.stage


def read_stage(name):
    record = json.loads((OUT / f'stage-{name}.json').read_text())
    if record['status'] != 'success' or record['stage'] != name:
        raise ValueError(f'invalid upstream stage: {name}')
    return record['result']


def previous():
    parents = CONFIG['dependencies'][STAGE]
    if len(parents) != 1:
        raise ValueError(f'{STAGE} requires an explicit parent selection')
    return read_stage(parents[0])


def write_json(name, value):
    (OUT / name).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')
    return value


def write_pickle(name, value):
    (OUT / name).write_bytes(pickle.dumps(value, protocol=4))


def write_csv(name, rows):
    with (OUT / name).open('w', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def report(name, title, value):
    (OUT / name).write_text('<!doctype html><meta charset="utf-8"><title>' + html.escape(title) + '</title><h1>' + html.escape(title) + '</h1><pre>' + html.escape(json.dumps(value, indent=2)) + '</pre>\n')


def regression(rows):
    xs = [row[0] for row in rows]
    ys = [row[1] for row in rows]
    mean_x, mean_y = statistics.mean(xs), statistics.mean(ys)
    denominator = sum((x - mean_x) ** 2 for x in xs)
    if denominator <= 0:
        raise ValueError('training inputs have zero variance')
    weight = sum((x - mean_x) * (y - mean_y) for x, y in rows) / denominator
    return {'weight': weight, 'bias': mean_y - weight * mean_x}


def predict(model, x):
    return model['weight'] * x + model['bias']


def rmse(model, rows):
    return math.sqrt(statistics.mean((predict(model, x) - y) ** 2 for x, y in rows))


def require(condition, message):
    if not condition:
        raise ValueError(message)


def run_stage():
    started = time.time_ns()
    parents = CONFIG['dependencies'][STAGE]
    for parent in parents:
        read_stage(parent)
    result = compute()
    require(isinstance(result, dict) and result, 'activity produced no domain result')
    record = {
        'showcase': CONFIG['slug'], 'stage': STAGE, 'status': 'success',
        'validationMode': 'local-workload', 'startedAtUnixNs': started,
        'finishedAtUnixNs': time.time_ns(),
        'inputDigest': hashlib.sha256(json.dumps(INPUT, sort_keys=True).encode()).hexdigest(),
        'dependencies': parents, 'result': result,
    }
    write_json(f'stage-{STAGE}.json', record)
    print(json.dumps({'activity': STAGE, 'status': 'success', 'resultKeys': list(result)}))

def assisted_analysis():
    if STAGE == 'prepare-experiment':
        require(INPUT['steps'] >= 10 and INPUT['decay'] > 0, 'invalid decay experiment')
        return {'initial': INPUT['initial'], 'decay': INPUT['decay'], 'step': INPUT['step'], 'steps': INPUT['steps']}
    if STAGE == 'simulation':
        setup = previous()
        # Euler integration of dC/dt = -k C, with a bounded stability step.
        require(0 < setup['decay'] * setup['step'] < 1, 'unstable integration step')
        value = setup['initial']
        samples = []
        for i in range(setup['steps'] + 1):
            samples.append({'time': i * setup['step'], 'concentration': value})
            value -= setup['step'] * setup['decay'] * value
        return {'samples': samples, 'setup': setup}
    if STAGE == 'measurements':
        data = previous()
        for sample in data['samples']:
            sample['analytic'] = data['setup']['initial'] * math.exp(-data['setup']['decay'] * sample['time'])
        return data
    if STAGE == 'statistics':
        data = previous()
        errors = [abs(s['concentration'] - s['analytic']) for s in data['samples']]
        return {'meanAbsoluteError': statistics.mean(errors), 'maxError': max(errors), 'count': len(errors), 'final': data['samples'][-1]}
    if STAGE == 'ai-interpretation':
        data = previous()
        # Fit the log-linear decay model from observations, independently from statistics.
        rows = [(s['time'], math.log(s['concentration'])) for s in data['samples']]
        model = regression(rows)
        rate = -model['weight']
        interpretation = f'Observed decay rate {rate:.6f}; concentration decreases with time. The fitted half-life is {math.log(2) / rate:.4f} time units.'
        return {'fittedDecayRate': rate, 'halfLife': math.log(2) / rate, 'method': 'log-linear regression', 'interpretation': interpretation}
    if STAGE == 'validate':
        measured = read_stage('statistics')
        inferred = read_stage('ai-interpretation')
        require(measured['maxError'] < INPUT['maxError'], 'numerical integration exceeded error budget')
        require(abs(inferred['fittedDecayRate'] - INPUT['decay']) < 0.02, 'inferred decay rate is inconsistent')
        return {'statistics': measured, 'inference': inferred, 'checksPassed': 2}
    if STAGE == 'report':
        result = previous()
        write_json('analysis.json', result)
        (OUT / 'interpretation.md').write_text('# Decay experiment\n\n' + result['inference']['interpretation'] + '\n')
        return result
    raise ValueError(STAGE)


def compute():
    return assisted_analysis()

if __name__ == '__main__':
    run_stage()
